
const TERMS=Array.isArray(window.PH_DATA)?window.PH_DATA:[], CHAPTERS=window.PH_CHAPTERS||{}, CASES=Array.isArray(window.PH_CASES)?window.PH_CASES:[], COMM=Array.isArray(window.PH_COMM)?window.PH_COMM:[];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
window.__session1EngineReady=false;
const store={get(k,d){try{return JSON.parse(localStorage.getItem('pheng_'+k))??d}catch{return d}},set(k,v){try{localStorage.setItem('pheng_'+k,JSON.stringify(v));return true}catch{return false}}};
const activityDefaults={flash:0,pron:0,practice:[],cases:[],comm:[],group:[],test:[]};
let saved=store.get('saved',{});if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
let pronRatings=store.get('pronRatings',{});if(!pronRatings||typeof pronRatings!=='object'||Array.isArray(pronRatings))pronRatings={};for(const [word,state] of Object.entries(saved)){if(state?.pron&&!pronRatings[word])pronRatings[word]=state.pron}
let activity={...activityDefaults,...store.get('activity',{})};
for(const key of ['practice','cases','comm','group','test'])if(!Array.isArray(activity[key]))activity[key]=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const prefersReducedMotion=()=>document.body.classList.contains('reduce-motion')||(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const scrollBehavior=()=>prefersReducedMotion()?'auto':'smooth';
const termByWord=w=>TERMS.find(t=>t.word===w);
function speak(text){if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';const voices=speechSynthesis.getVoices?.()||[];const british=voices.find(v=>String(v.lang).toLowerCase()==='en-gb')||voices.find(v=>String(v.lang).toLowerCase().startsWith('en-gb'));if(british)u.voice=british;u.rate=.82;speechSynthesis.speak(u)}
function showPage(id,fromHistory=false){const target=$('#'+id);if(!target?.classList.contains('page'))id='home';if(id!=='groupactivity'&&window.__session1EngineReady&&typeof stopSession1Timer==='function')stopSession1Timer();$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));$$('[data-page]').forEach(b=>{const a=b.dataset.page===id;b.classList.toggle('active',a);if(a)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$$('.nav-menu-group').forEach(d=>{d.open=false;const pages=(d.dataset.navPages||'').split(',');d.classList.toggle('active',pages.includes(id))});if(!fromHistory){const wanted=id==='home'?'':'#'+id;if(location.hash!==wanted)location.hash=wanted}if(id==='groupactivity'&&typeof showGroupLibrary==='function')showGroupLibrary(false);updateAll();window.scrollTo({top:0,behavior:scrollBehavior()})}window.showPage=showPage;
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));
function chapterLabel(n){return CHAPTERS[n]?`Chapter ${n} · ${CHAPTERS[n].title}`:`Chapter ${n}`}
function updateAll(){const vals=Object.values(saved), mastered=vals.filter(x=>x.status==='mastered').length, review=vals.filter(x=>x.status==='review').length, pronVals=Object.values(pronRatings), pronRated=pronVals.length, pronReview=pronVals.filter(x=>x==='review'||x==='tricky').length;['homeSaved','nbSaved','pSaved','navSavedCount'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=vals.length});['homeMastered','nbMastered','pMastered'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=mastered});['homeReview','nbReview'].forEach(id=>{const e=$('#'+id);if(e)e.textContent=review});const setText=(id,value)=>{const e=$('#'+id);if(e)e.textContent=value};setText('pFlash',activity.flash||0);setText('pPron',activity.pron||0);setText('pCases',activity.cases.length);setText('pComm',activity.comm.length);setText('pGroup',activity.group.length);setText('pronRated',pronRated);setText('pronReview',pronReview);setText('groupCompletedCount',activity.group.length);const pp=activity.practice||[];const recent=pp.slice(-3).filter(x=>x&&x.total>0);setText('pPractice',recent.length?Math.round(recent.reduce((a,x)=>a+x.score/x.total,0)/recent.length*100)+'%':'—');updatePlan();if($('#notebook')?.classList.contains('active'))renderNotebook();}
function saveState(){store.set('saved',saved);store.set('pronRatings',pronRatings);store.set('activity',activity);updateAll()}
function refreshDictionary(){if($('#search')?.classList.contains('active'))dictSearch($('#searchInput').value)}
function setSaved(word,status){saved[word]=saved[word]||{status:'review',seen:0};if(status)saved[word].status=status;saveState();renderLexicon();refreshDictionary()}
function removeSaved(word){delete saved[word];saveState();renderLexicon();refreshDictionary()}

// Home
$('#statTerms').textContent=TERMS.length;$('#statChapters').textContent=Object.keys(CHAPTERS).length;$('#statSections').textContent=new Set(TERMS.map(t=>t.section)).size;
const day=Math.floor(Date.now()/86400000), spot=TERMS.length?TERMS[day%TERMS.length]:null;if(spot)$('#spotlightContent').innerHTML=`<div class="spotlight-word">${esc(spot.word)}</div><div class="spotlight-fr">${esc(spot.fr)}</div><p>${esc(spot.definition)}</p><button onclick="speak('${spot.word.replaceAll("'","\\'")}')">🔊 Listen</button>`;else $('#spotlightContent').innerHTML='<p>Vocabulary data could not be loaded.</p>';
function showFive(){const five=shuffle(TERMS).slice(0,5);$('#quickWords').hidden=false;$('#quickWords').innerHTML=five.map(t=>`<article class="quick-word"><strong>${esc(t.word)}</strong><span>${esc(t.fr)}</span><p>${esc(t.definition)}</p><button onclick="speak('${t.word.replaceAll("'","\\'")}')">🔊</button></article>`).join('');$('#quickWords').scrollIntoView({behavior:scrollBehavior()})}
$('#learnFive').onclick=showFive;$('#startHereWords').onclick=showFive;$('#quickRevision').onclick=()=>{showPage('flashcards');startFlash()};$('#fiveMinuteBoost').onclick=()=>{showPage('practice');$('#practiceSize').value='5';startPractice()};$('#startHereTour').onclick=()=>{showPage('lexicon');$('#query').value='';$('#chapter').value='1';renderLexicon()};$('#surpriseMe').onclick=()=>{const pages=['lexicon','flashcards','practice','cases','communication','groupactivity','pronunciation'];showPage(pages[Math.floor(Math.random()*pages.length)])};

// Lexicon
const chapterSelects=['#chapter','#flashChapter'];for(const sel of chapterSelects){Object.keys(CHAPTERS).forEach(n=>{const o=document.createElement('option');o.value=n;o.textContent=chapterLabel(n);$(sel).appendChild(o)})}
[...new Set(TERMS.map(t=>t.section))].sort().forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;$('#section').appendChild(o)});
function card(t){const state=saved[t.word];return `<article class="term-card"><div class="term-head"><div><div class="badges"><span class="badge">${esc(chapterLabel(t.chapter))}</span><span class="badge">${esc(t.section)}</span><span class="badge">${esc(t.level)}</span></div><h3>${esc(t.word)}</h3><div class="ipa">${esc(t.ipa)}</div><div class="fr">${esc(t.fr)}</div></div><button onclick="speak('${t.word.replaceAll("'","\\'")}')">🔊 Listen</button></div><p>${esc(t.definition)}</p><p class="example"><strong>In context:</strong> ${esc(t.example)}</p><p><strong>Collocations:</strong> ${t.collocations.map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</p><p><strong>Related:</strong> ${t.related.map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</p><div class="term-actions">${state?`<button class="saved" onclick="removeSaved('${t.word.replaceAll("'","\\'")}')">♥ Saved</button><button class="${state.status==='mastered'?'mastered':''}" onclick="setSaved('${t.word.replaceAll("'","\\'")}','mastered')">✓ Mastered</button><button onclick="setSaved('${t.word.replaceAll("'","\\'")}','review')">↻ Review</button>`:`<button onclick="setSaved('${t.word.replaceAll("'","\\'")}','review')">♡ Save word</button>`}</div></article>`}
function filtered(){const q=$('#query').value.trim().toLowerCase(), ch=$('#chapter').value, sec=$('#section').value, lev=$('#level').value;return TERMS.filter(t=>(!q||JSON.stringify(t).toLowerCase().includes(q))&&(!ch||String(t.chapter)===ch)&&(!sec||t.section===sec)&&(!lev||t.level===lev))}
function renderLexicon(){const f=filtered();$('#count').textContent=`${f.length} term${f.length!==1?'s':''}`;$('#results').innerHTML=f.map(card).join('')||'<div class="panel">No matching term.</div>'}
['#query','#chapter','#section','#level'].forEach(s=>$(s).addEventListener('input',renderLexicon));renderLexicon();

// Dictionary
function dictSearch(q){q=q.trim().toLowerCase();if(q.length<2){$('#searchCount').textContent='';$('#searchResults').innerHTML='<div class="practice-welcome"><div>⌨️</div><h3>Type at least 2 characters.</h3></div>';return}const hits=TERMS.filter(t=>[t.word,t.fr,t.definition,t.example,...t.collocations,...t.related].join(' ').toLowerCase().includes(q));$('#searchCount').textContent=`${hits.length} match${hits.length!==1?'es':''}`;$('#searchResults').innerHTML=hits.slice(0,25).map(card).join('')||'<div class="panel">No match. Try another word or French equivalent.</div>'}
$('#searchInput').oninput=e=>dictSearch(e.target.value);$('#randomTerm').onclick=()=>{if(!TERMS.length)return;const t=TERMS[Math.floor(Math.random()*TERMS.length)];$('#searchInput').value=t.word;dictSearch(t.word)};

// Flashcards
let flashDeck=[],fi=0,flashStats={again:0,hard:0,got:0},flashRatingsThisSession={},flipped=false;
function sourceTerms(src){if(src==='__saved'||src==='saved')return TERMS.filter(t=>saved[t.word]);if(src==='__review'||src==='review')return TERMS.filter(t=>saved[t.word]?.status==='review');if(src&&/^\d+$/.test(src))return TERMS.filter(t=>String(t.chapter)===src);return TERMS}
function startFlash(){const pool=sourceTerms($('#flashChapter').value);const size=$('#flashSize').value==='all'?pool.length:+$('#flashSize').value;flashDeck=shuffle(pool).slice(0,size);fi=0;flashStats={again:0,hard:0,got:0};flashRatingsThisSession={};renderFlash()}
function renderFlash(){if(!flashDeck.length){$('#flash').innerHTML='<div class="panel">No cards in this deck yet.</div>';$('#flashRating').hidden=true;$('#flashProgress').textContent='0 / 0';$('#flashProgressBar').style.width='0%';return}const t=flashDeck[fi];flipped=false;$('#flash').innerHTML=`<div class="flashcard" id="flashCard" tabindex="0" role="button" aria-label="Reveal ${esc(t.word)}"><div><div class="big">${esc(t.word)}</div><div class="ipa">${esc(t.ipa)}</div><p>Click, press Enter or press Space to reveal.</p><button type="button" onclick="event.stopPropagation();speak('${t.word.replaceAll("'","\\'")}')">🔊 Listen</button></div></div>`;$('#flashRating').hidden=true;$('#flashProgress').textContent=`${fi+1} / ${flashDeck.length}`;$('#flashProgressNote').textContent=chapterLabel(t.chapter);$('#flashProgressBar').style.width=((fi+1)/flashDeck.length*100)+'%';$('#flashAgainCount').textContent=flashStats.again;$('#flashHardCount').textContent=flashStats.hard;$('#flashGotCount').textContent=flashStats.got;$('#flashCard').onclick=flip;$('#flashCard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}}}
function flip(){if(flipped||!flashDeck.length)return;flipped=true;const t=flashDeck[fi];$('#flashCard').setAttribute('aria-label',`Definition of ${t.word}`);$('#flashCard').innerHTML=`<div><div class="big">${esc(t.word)}</div><div class="fr">${esc(t.fr)}</div><p>${esc(t.definition)}</p><p class="example">${esc(t.example)}</p></div>`;$('#flashRating').hidden=false}
function finishFlash(){if(!flashDeck.length)return;$('#flashRating').hidden=true;$('#flashProgress').textContent=`${flashDeck.length} / ${flashDeck.length}`;$('#flashProgressNote').textContent='Session complete.';$('#flashProgressBar').style.width='100%';$('#flashAgainCount').textContent=flashStats.again;$('#flashHardCount').textContent=flashStats.hard;$('#flashGotCount').textContent=flashStats.got;$('#flash').innerHTML=`<div class="test-score"><h3>Flashcard session complete</h3><p><strong>${flashStats.got}</strong> got it · <strong>${flashStats.hard}</strong> hard · <strong>${flashStats.again}</strong> again</p><p>Difficult words have been kept in your review list.</p><button class="primary-action" id="flashAgain">Start a new session</button></div>`;$('#flashAgain').onclick=startFlash}
function advanceFlash(){if(!flashDeck.length)return;fi++;if(fi>=flashDeck.length)finishFlash();else renderFlash()}
function rateFlash(r){if(!flashDeck.length||fi>=flashDeck.length)return;const t=flashDeck[fi],previous=flashRatingsThisSession[t.word];if(previous&&flashStats[previous]>0)flashStats[previous]--;else activity.flash=(activity.flash||0)+1;flashRatingsThisSession[t.word]=r;flashStats[r]++;saved[t.word]=saved[t.word]||{status:'review'};if(r==='got')saved[t.word].status='mastered';else saved[t.word].status='review';saveState();advanceFlash()}
$$('[data-flash-rate]').forEach(b=>b.onclick=()=>rateFlash(b.dataset.flashRate));$('#newFlashSession').onclick=startFlash;$('#next').onclick=advanceFlash;$('#prev').onclick=()=>{if(flashDeck.length&&fi>0){fi--;renderFlash()}};$('#shuffle').onclick=()=>{if(flashDeck.length&&fi<flashDeck.length){flashDeck=[...flashDeck.slice(0,fi),...shuffle(flashDeck.slice(fi))];renderFlash()}};

// Practice
let practiceMode='definition',practiceDeck=[],pi=0,pcorrect=0,pmissed=0,pstreak=0,answered=false;
const modeNames={definition:'Definition Detective',french:'French → English',cloze:'Public Health Gap',listen:'Listen & Spot',collocation:'Collocation Match',mix:'Mix It Up'};
$$('[data-practice-mode]').forEach(b=>b.onclick=()=>{$$('[data-practice-mode]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');practiceMode=b.dataset.practiceMode;$('#practiceModeName').textContent=modeNames[practiceMode]});
function distractors(t,n=3){return shuffle(TERMS.filter(x=>x.word!==t.word)).slice(0,n)}
function makeQ(t,mode){if(mode==='mix')mode=shuffle(['definition','french','cloze','listen','collocation'])[0];let prompt,answer=t.word,opts;if(mode==='definition'){prompt=t.definition;opts=shuffle([t,...distractors(t)]).map(x=>x.word)}else if(mode==='french'){prompt=`Translate into professional English: “${t.fr}”`;opts=shuffle([t,...distractors(t)]).map(x=>x.word)}else if(mode==='cloze'){const re=new RegExp(t.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');prompt=t.example.replace(re,'_____');if(prompt===t.example)prompt=`Which term best fits this public-health context? ${t.example}`;opts=shuffle([t,...distractors(t)]).map(x=>x.word)}else if(mode==='listen'){prompt='Listen, then choose the term you heard.';opts=shuffle([t,...distractors(t)]).map(x=>x.word);setTimeout(()=>speak(t.word),200)}else{prompt='Choose a natural collocation with the target term: '+t.word;answer=t.collocations[0];const candidates=shuffle(TERMS.filter(x=>x.word!==t.word).map(x=>x.collocations?.[0]).filter(x=>x&&x!==answer));opts=shuffle([answer,...[...new Set(candidates)].slice(0,3)])}return{prompt,answer,opts,mode}}
function startPractice(){let pool=sourceTerms($('#practiceSource').value);if(!pool.length){$('#practiceBox').innerHTML='<div class="panel">Save some vocabulary first, or choose all vocabulary.</div>';return}practiceDeck=shuffle(pool).slice(0,Math.min(+$('#practiceSize').value,pool.length));pi=0;pcorrect=0;pmissed=0;pstreak=0;$('#practiceSessionBar').hidden=false;renderPractice()}
function renderPractice(){if(pi>=practiceDeck.length){const total=pcorrect+pmissed;activity.practice.push({score:pcorrect,total,date:Date.now()});$('#practiceProgress').textContent=`Session complete · ${total} question${total!==1?'s':''}`;$('#practiceCorrect').textContent=pcorrect;$('#practiceMissed').textContent=pmissed;$('#practiceStreak').textContent=pstreak;$('#practiceProgressBar').style.width='100%';saveState();$('#practiceBox').innerHTML=`<div class="test-score"><h3>Session complete</h3><p class="big">${pcorrect}/${total}</p><button class="primary-action" onclick="startPractice()">Play again</button></div>`;return}answered=false;const t=practiceDeck[pi],q=makeQ(t,practiceMode);$('#practiceProgress').textContent=`Question ${pi+1} / ${practiceDeck.length}`;$('#practiceCorrect').textContent=pcorrect;$('#practiceMissed').textContent=pmissed;$('#practiceStreak').textContent=pstreak;$('#practiceProgressBar').style.width=((pi+1)/practiceDeck.length*100)+'%';$('#practiceBox').innerHTML=`<article class="practice-question"><span class="eyebrow">${esc(modeNames[q.mode]||modeNames[practiceMode])}</span><h3>${esc(q.prompt)}</h3>${q.mode==='listen'?'<button onclick="speak(\''+t.word.replaceAll("'","\\'")+'\')">🔊 Play again</button>':''}<div class="option-grid">${q.opts.map(o=>`<button data-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div><div id="practiceFeedback"></div></article>`;$$('#practiceBox [data-answer]').forEach(b=>b.onclick=()=>answerPractice(b,q.answer,t))}
function answerPractice(btn,answer,t){if(answered)return;answered=true;const ok=btn.dataset.answer===answer;btn.classList.add(ok?'correct':'wrong');$$('#practiceBox [data-answer]').forEach(b=>{if(b.dataset.answer===answer)b.classList.add('correct');b.disabled=true});if(ok){pcorrect++;pstreak++}else{pmissed++;pstreak=0;saved[t.word]=saved[t.word]||{status:'review'};saved[t.word].status='review'}$('#practiceFeedback').innerHTML=`<div class="feedback"><strong>${ok?'Correct.':'Not quite.'}</strong> ${esc(t.word)} — ${esc(t.definition)}<br><button id="practiceNext">Next →</button></div>`;saveState();$('#practiceNext').onclick=()=>{pi++;renderPractice()}}
$('#startPractice').onclick=startPractice;window.startPractice=startPractice;

// Cases
function renderCases(){const area=$('#caseArea').value,f=CASES.filter(c=>area==='all'||c.area===area);$('#caseCount').textContent=f.length;$('#caseGrid').innerHTML=f.map((c,i)=>`<article class="case-card"><span class="eyebrow">${esc(c.area)}</span><h3>${esc(c.title)}</h3><p>${esc(c.scenario)}</p><button class="primary-action" data-case="${CASES.indexOf(c)}">Open case →</button></article>`).join('');$$('[data-case]').forEach(b=>b.onclick=()=>openCase(+b.dataset.case))}
function openCase(i){const c=CASES[i],mode=$('#caseDifficulty').value;$('#caseWorkspace').hidden=false;$('#caseWorkspace').innerHTML=`<button class="workspace-close" id="closeCaseWorkspace" type="button">× Close</button><span class="eyebrow">${esc(c.area)} · ${esc(mode)}</span><h3>${esc(c.title)}</h3><p>${esc(c.scenario)}</p><div class="support-box"><strong>Your task</strong><p>${esc(c.prompt)}</p>${mode==='guided'?`<p><strong>Useful terms:</strong> ${c.terms.map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</p>`:''}</div><textarea id="caseAnswer" rows="7" style="width:100%" placeholder="Write or prepare your answer here. Nothing is uploaded."></textarea><div class="card-actions"><button id="revealCase">Reveal model</button><button id="doneCase">Mark as explored</button></div><div id="caseModel"></div>`;$('#closeCaseWorkspace').onclick=()=>{$('#caseWorkspace').hidden=true};$('#caseWorkspace').scrollIntoView({behavior:scrollBehavior()});$('#revealCase').onclick=()=>$('#caseModel').innerHTML=`<div class="model"><strong>Possible model</strong><p>${esc(c.model)}</p></div>`;$('#doneCase').onclick=()=>{activity.cases=[...new Set([...(activity.cases||[]),i])];saveState();$('#doneCase').textContent='✓ Explored'}}
function closeCaseWorkspace(){if($('#caseWorkspace'))$('#caseWorkspace').hidden=true}$('#caseArea').onchange=()=>{closeCaseWorkspace();renderCases()};$('#caseDifficulty').onchange=()=>{closeCaseWorkspace();renderCases()};$('#randomCase').onclick=()=>{if(CASES.length)openCase(Math.floor(Math.random()*CASES.length))};renderCases();

// Communication
function renderComm(){const sk=$('#communicationSkill').value,f=COMM.filter(c=>sk==='all'||c.skill===sk);$('#communicationCount').textContent=f.length;$('#communicationGrid').innerHTML=f.map(c=>`<article class="comm-card"><span class="eyebrow">${esc(c.skill)}</span><h3>${esc(c.title)}</h3><p>${esc(c.prompt)}</p><button class="primary-action" data-comm="${COMM.indexOf(c)}">Open task →</button></article>`).join('');$$('[data-comm]').forEach(b=>b.onclick=()=>openComm(+b.dataset.comm))}
function openComm(i){const c=COMM[i],mode=$('#communicationMode').value;$('#communicationWorkspace').hidden=false;$('#communicationWorkspace').innerHTML=`<button class="workspace-close" id="closeCommunicationWorkspace" type="button">× Close</button><span class="eyebrow">${esc(c.skill)} · ${esc(mode)}</span><h3>${esc(c.title)}</h3><p>${esc(c.prompt)}</p>${mode==='guided'?`<div class="support-box"><strong>Useful language</strong>${c.support.map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}<textarea rows="7" style="width:100%" placeholder="Prepare your answer here. Nothing is uploaded."></textarea><div class="card-actions"><button id="revealComm">Reveal model</button><button id="doneComm">Mark as explored</button></div><div id="commModel"></div>`;$('#closeCommunicationWorkspace').onclick=()=>{$('#communicationWorkspace').hidden=true};$('#communicationWorkspace').scrollIntoView({behavior:scrollBehavior()});$('#revealComm').onclick=()=>$('#commModel').innerHTML=`<div class="model"><strong>Possible model</strong><p>${esc(c.model)}</p></div>`;$('#doneComm').onclick=()=>{activity.comm=[...new Set([...(activity.comm||[]),i])];saveState();$('#doneComm').textContent='✓ Explored'}}
function closeCommunicationWorkspace(){if($('#communicationWorkspace'))$('#communicationWorkspace').hidden=true}$('#communicationSkill').onchange=()=>{closeCommunicationWorkspace();renderComm()};$('#communicationMode').onchange=()=>{closeCommunicationWorkspace();renderComm()};$('#randomCommunication').onclick=()=>{if(COMM.length)openComm(Math.floor(Math.random()*COMM.length))};renderComm();

// Pronunciation
const tricky=TERMS.filter(t=>t.word.length>15||/epidemi|pharmaco|random|validity|significance|inequal|determinant|environment/i.test(t.word));let pronDeck=[],pri=0;
function pronPool(){const s=$('#pronSource').value;if(s==='tricky')return tricky;if(s==='review')return TERMS.filter(t=>pronRatings[t.word]==='review'||pronRatings[t.word]==='tricky');return TERMS}
function startPron(){pronDeck=shuffle(pronPool()).slice(0,+$('#pronSize').value);pri=0;renderPron()}
function renderPron(){
  if(!pronDeck.length){
    $('#pronWorkspace').innerHTML='<div class="practice-welcome"><h3>No words in this set yet.</h3></div>';
    return;
  }
  const t=pronDeck[pri];
  $('#pronWorkspace').innerHTML=`<div class="pron-card"><div class="pron-progress">${pri+1} / ${pronDeck.length} · ${esc(chapterLabel(t.chapter))}</div><div class="pron-word">${esc(t.word)}</div><div class="pron-ipa">${esc(t.ipa)}</div><p>${esc(t.example)}</p><button class="primary-action" onclick="speak('${t.word.replaceAll("'","\\'")}')">🔊 Listen in British English</button><div class="pron-ratings"><button data-pr="easy">✓ Easy</button><button data-pr="tricky">◐ Tricky</button><button data-pr="review">↻ Again</button></div></div>`;
  $$('[data-pr]').forEach(b=>{
    b.onclick=()=>{
      pronRatings[t.word]=b.dataset.pr;
      activity.pron=(activity.pron||0)+1;
      saveState();
      pri++;
      if(pri>=pronDeck.length){
        $('#pronWorkspace').innerHTML='<div class="test-score"><h3>Workout complete.</h3><button class="primary-action" id="pronAgain">New workout</button></div>';
        $('#pronAgain').onclick=startPron;
      }else{
        renderPron();
      }
    };
  });
}
