function recomputeSession1Scores(choices){const scores={...SESSION1_BASE_SCORES};choices.forEach((choiceId,index)=>{const option=SESSION1_STEPS[index]?.options.find(o=>o.id===choiceId);if(option)for(const [key,val] of Object.entries(option.effect))scores[key]=clampGroupScore(scores[key]+val)});return scores}
function normaliseGroupSession1(){
 if(!groupSession1||typeof groupSession1!=='object')groupSession1={};
 const rawChoices=Array.isArray(groupSession1.choices)?groupSession1.choices:[];
 const validChoices=[];
 for(let index=0;index<Math.min(rawChoices.length,SESSION1_STEPS.length);index++){
  const choiceId=rawChoices[index];
  if(!SESSION1_STEPS[index]?.options.some(o=>o.id===choiceId))break;
  validChoices.push(choiceId);
 }
 groupSession1.choices=validChoices;
 groupSession1.scores=recomputeSession1Scores(validChoices);
 groupSession1.engineVersion=SESSION1_ENGINE_VERSION;
 const rawOutcome=groupSession1.outcome;
 const outcomeIndex=rawOutcome?.stepIndex;
 const validOutcome=Number.isInteger(outcomeIndex)&&outcomeIndex===validChoices.length-1&&outcomeIndex>=0&&outcomeIndex<SESSION1_STEPS.length&&SESSION1_STEPS[outcomeIndex]?.options.some(o=>o.id===validChoices[outcomeIndex]);
 groupSession1.completed=Boolean(groupSession1.completed&&validChoices.length===SESSION1_STEPS.length&&!validOutcome);
 if(validOutcome&&!groupSession1.completed){
  groupSession1.step=outcomeIndex;
  groupSession1.outcome={stepIndex:outcomeIndex,choiceId:validChoices[outcomeIndex],consistency:compatibilityNote(outcomeIndex,validChoices[outcomeIndex])};
 }else{
  groupSession1.step=validChoices.length;
  groupSession1.outcome=null;
 }
 saveGroupSession1();
}
